import java.util.zip.GZIPInputStream
internal object AsciiDocChompProof {
private fun decode(v:JsonElement):Doc<String>{val o=v.jsonObject;fun child()=decode(o.getValue("doc"))
return when(o.getValue("kind").jsonPrimitive.content){"text"->DocLayout.Text.literal(o.getValue("text").jsonPrimitive.content);"empty"->Doc.Empty;"space"->Doc.BreakingSpace;"cr"->Doc.CarriageReturn;"newline"->Doc.NewLine;"blank"->Doc.BlankLines(o.getValue("count").jsonPrimitive.long);"concat"->Doc.Concat(decode(o.getValue("left")),decode(o.getValue("right")));"prefix"->Doc.Prefixed(o.getValue("prefix").jsonPrimitive.content,child());"flush"->Doc.Flush(child());"before"->Doc.BeforeNonBlank(child());"link"->Doc.Linked("target",child());else->error("doc")}}
private fun encode(d:Doc<String>):JsonElement=buildJsonObject{when(d){Doc.Empty->put("kind","empty");is Doc.Text->{put("kind","text");put("width",d.width);put("text",d.value)};Doc.BreakingSpace->put("kind","space");Doc.CarriageReturn->put("kind","cr");Doc.NewLine->put("kind","newline");is Doc.BlankLines->{put("kind","blank");put("count",d.count)};is Doc.Concat->{put("kind","concat");put("left",encode(d.left));put("right",encode(d.right))};is Doc.Prefixed->{put("kind","prefix");put("prefix",d.prefix);put("doc",encode(d.doc))};is Doc.Flush->{put("kind","flush");put("doc",encode(d.doc))};is Doc.BeforeNonBlank->{put("kind","before");put("doc",encode(d.doc))};is Doc.Linked->{put("kind","link");put("target",d.link);put("doc",encode(d.doc))};else->error("unexpected doc")}}
private fun canonical(d:Doc<String>):Doc<String>{
 fun flatten(x:Doc<String>,out:MutableList<Doc<String>>){when(x){is Doc.Concat->{flatten(x.left,out);flatten(x.right,out)};Doc.Empty->Unit;else->out.add(x)}}
 return when(d){is Doc.Concat->{val leaves=mutableListOf<Doc<String>>();flatten(d,leaves);DocLayout.Text.hcat(leaves.map(::canonical))};is Doc.Prefixed->d.copy(doc=canonical(d.doc));is Doc.Flush->d.copy(doc=canonical(d.doc));is Doc.BeforeNonBlank->d.copy(doc=canonical(d.doc));is Doc.Linked->d.copy(doc=canonical(d.doc));else->d}
}
fun run(args:Array<String>){var count=0;val chomp=AsciiDocChomp();GZIPInputStream(File(args[0]).inputStream()).bufferedReader().useLines{lines->lines.forEach{line->val r=Json.parseToJsonElement(line).jsonObject;val q=r.getValue("request").jsonObject;val result=chomp.apply(decode(q.getValue("doc")));val e=r.getValue("expected").jsonObject;check(encode(canonical(result))==encode(canonical(decode(e.getValue("doc"))))){q.getValue("name").toString()+" structure"};check(DocLayout.Text.render(null,result)==e.getValue("output").jsonPrimitive.content){q.getValue("name").toString()+" output"};e["offset"]?.let{check(DocLayout.Text.offset(result)==it.jsonPrimitive.long){"offset "+q.getValue("name")+" expected="+it+" actual="+DocLayout.Text.offset(result)}};e["minOffset"]?.let{check(DocLayout.Text.minOffset(result)==it.jsonPrimitive.long){"minOffset "+q.getValue("name")+" expected="+it+" actual="+DocLayout.Text.minOffset(result)}};e["empty"]?.let{check(DocLayout.Text.isEmpty(result)==it.jsonPrimitive.boolean){"empty "+q.getValue("name")}};count++}};println("PASS $count original chomp structures/output")}
